/* Browser-local editor; exported stories require only HTML and CSS. */
const $=id=>document.getElementById(id), editor=$('workskin');
let previewView=false,visualView=false;
let graphView=false, graphNodes=new Map(), graphSelection=null, graphZoom=0.8, graphBounds={width:1,height:1};
let css='', savedRange=null, history=[], cursor=-1, timer, originalView=false;
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=t=>t.split(/\n\s*\n/).filter(x=>x.trim()).map(x=>'<p>'+esc(x).replace(/\n/g,'<br>')+'</p>').join('');
const slot=h=>`<div data-editable="true" contenteditable="true">${h||'<p><br></p>'}</div>`;
const wrap=(cls,h)=>`<div class="widget ${cls}" contenteditable="false" data-widget="${cls}">${h}</div>`;
function notice(s){$('status').textContent=s;}
const DRAFT_KEY='paper-studio-document-v4', BACKUP_KEY='paper-studio-backup-v4';
let lastBackupAt=0;
let draftDatabase,indexedReadFailed=false;
function openDraftDatabase(){if(!draftDatabase)draftDatabase=new Promise((resolve,reject)=>{const request=indexedDB.open('paper-studio-drafts',1);request.onupgradeneeded=()=>request.result.createObjectStore('documents');const timeout=setTimeout(()=>reject(Error('浏览器数据库不可用')),2000);request.onsuccess=()=>{clearTimeout(timeout);resolve(request.result);};request.onblocked=()=>{clearTimeout(timeout);reject(Error('数据库被阻止'));};request.onerror=()=>{clearTimeout(timeout);reject(request.error);};});return draftDatabase;}
async function indexedDraft(mode,record,storageKey=DRAFT_KEY){const database=await openDraftDatabase();return new Promise((resolve,reject)=>{let finished=false;const transaction=database.transaction('documents',mode==='get'?'readonly':'readwrite'),store=transaction.objectStore('documents');const request=mode==='get'?store.get(storageKey):store.put(record,storageKey);const timer=setTimeout(()=>{if(finished)return;finished=true;try{transaction.abort();}catch{}reject(Error('浏览器存储读取超时'));},2000);transaction.oncomplete=()=>{if(finished)return;finished=true;clearTimeout(timer);resolve(request.result);};const fail=()=>{if(finished)return;finished=true;clearTimeout(timer);reject(transaction.error||Error('浏览器存储不可用'));};transaction.onerror=fail;transaction.onabort=fail;});}

async function readIndexedDraft(storageKey=DRAFT_KEY){try{const value=await indexedDraft('get',null,storageKey);indexedReadFailed=false;return value?parseDocument(JSON.stringify(value)):null;}catch{indexedReadFailed=true;return null;}}
function backupToIndexed(record){if(indexedReadFailed){$('saveState').textContent='浏览器存储不可用';$('saveState').dataset.state='error';return;}indexedDraft('put',record).then(()=>{$('saveState').textContent='已自动保存';$('saveState').dataset.state='saved';$('saveState').title='已保存到本机浏览器数据库';}).catch(()=>{$('saveState').textContent='浏览器禁止自动保存';$('saveState').dataset.state='error';$('saveState').title='请保存或复制草稿；用完整浏览器打开文件后再试';});}
function documentRecord(){syncChapter();return {book:JSON.parse(JSON.stringify(book)),format:'paper-studio',version:1,editorVersion:3,savedAt:new Date().toISOString(),html:editor.innerHTML,assets:referencedMusicAssets(),images:referencedImageAssets(),settings:{storyFull:$('storyFull').checked,noCSS:$('noCSS').checked,storyTheme:$('storyTheme')?.value||'gray'}};}
function parseDocument(text){const doc=JSON.parse(text);if(!doc||doc.format!=='paper-studio'||doc.version!==1||typeof doc.html!=='string')throw Error('不是纸间的正文保存文件');const settings=doc.settings||{};return {...doc,settings:{sender:typeof settings.sender==='string'?settings.sender:'',recipient:typeof settings.recipient==='string'?settings.recipient:'',storyFull:typeof settings.storyFull==='boolean'?settings.storyFull:true,noCSS:typeof settings.noCSS==='boolean'?settings.noCSS:true,storyTheme:['black','white','gray'].includes(settings.storyTheme)?settings.storyTheme:'gray'}};}
function readStored(key){try{const data=localStorage.getItem(key);return data?parseDocument(data):null;}catch{return null;}}
function persist(){if(!workLibraryReady)return false;const record=workspaceRecord();let prior=null;try{prior=localStorage.getItem(DRAFT_KEY);}catch{}$('count').textContent=editorText(editor).replace(/\s/g,'').length+' 字';try{localStorage.setItem(DRAFT_KEY,JSON.stringify(record));$('saveState').textContent='已自动保存';$('saveState').dataset.state='saved';$('saveState').title='自动保存于 '+new Date(record.savedAt).toLocaleTimeString();}catch{backupToIndexed(record);$('saveState').textContent='正在尝试备用保存';$('saveState').dataset.state='error';$('saveState').title='请点击「保存到本地」，把正文下载为文件。';return false;}if(prior&&Date.now()-lastBackupAt>30000){try{parseDocument(prior);localStorage.setItem(BACKUP_KEY,prior);lastBackupAt=Date.now();}catch{/* Current draft remains saved if the optional backup fails. */}}return true;}
function preserveBackup(){try{localStorage.setItem(BACKUP_KEY,JSON.stringify(workspaceRecord()));lastBackupAt=Date.now();}catch{/* A local document file can still be saved without browser storage. */}}
function sanitizeDocument(markup){const template=document.createElement('template');template.innerHTML=markup;const allowed=new Set(['P','DIV','SPAN','LABEL','BR','B','STRONG','EM','I','U','S','MARK','DETAILS','SUMMARY','BLOCKQUOTE','PRE','CODE','HR','BUTTON','DFN']);const discard=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','LINK','META','BASE','SVG','MATH','TEMPLATE']);for(const el of [...template.content.querySelectorAll('*')]){if(discard.has(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}for(const attr of [...el.attributes])if(!['class','data-editable','data-widget','data-field','data-placeholder','data-action','data-ending','data-node-id','data-next-id','data-sound-url','data-sound-volume','data-sound-mode','data-sound-loop','data-timeline-sounds','data-board-x','data-board-y','data-page-flash','data-story-set','data-story-action','data-story-require','data-story-when','data-story-auto','data-story-end','data-ending-id','data-story-return','data-story-explore','data-text-align','data-page-position','data-story-timed','data-story-seconds','data-story-timeout','tabindex','aria-label','aria-hidden'].includes(attr.name))el.removeAttribute(attr.name);}return template.innerHTML;}
function applySettings(settings){$('storyFull').checked=settings.storyFull;$('noCSS').checked=settings.noCSS;$('storyTheme').value=settings.storyTheme||'gray';}
function loadDocument(record,switching=false){rememberOriginalViewPosition();activeFontArt=null;fontRange=null;pendingConnection=null;selectedConnection=null;clearTimeout(timer);const migrated=migrateEditor(sanitizeDocument(record.html));preserveBackup();showView('edit');const oldMusic=musicAssets,oldImages=imageAssets;try{restoreMusicAssets(record.assets);restoreImageAssets(record.images);}catch(error){restoreMusicAssets(oldMusic);restoreImageAssets(oldImages);throw error;}if(!switching&&record.book&&workLibrary.has(record.book.id))record={...record,book:{...record.book,id:newChapterId(),title:(record.book.title||'未命名作品')+'（导入副本）'}};editor.innerHTML=migrated.html;applySettings({...record.settings,storyFull:record.editorVersion>=2?record.settings.storyFull:migrated.interactive});initBook(record);$('previewFrame').srcdoc='';if(!switching)importOtherWorks(record.library);history=[];cursor=-1;setEditable();savedRange=null;$('outputPanel').hidden=true;checkpoint();persist();paintWorks();showView('graph');notice(switching?'已切换作品；各作品的章节和素材独立保存。':'作品已导入，原有作品保留，可在顶部切换。');}
function historyState(){graphProjection(editor);const copy=editor.cloneNode(true);copy.querySelectorAll('[contenteditable]').forEach(el=>el.removeAttribute('contenteditable'));copy.querySelectorAll('details[open]').forEach(el=>el.removeAttribute('open'));copy.querySelectorAll(':scope .after-text-field').forEach(el=>{if(!el.textContent.trim()&&!el.querySelector('[data-widget],img,video,audio,.font-art,.inline-spoiler,.double-text'))el.remove();});return {html:copy.innerHTML,storyFull:$('storyFull').checked,noCSS:$('noCSS').checked,storyTheme:$('storyTheme')?.value||'gray'};}
function updateHistoryButtons(){$('undo').disabled=cursor<=0;$('redo').disabled=cursor>=history.length-1;$('undo').title='撤销（Ctrl / ⌘ + Z）';$('redo').title='重做（Ctrl / ⌘ + Shift + Z）';}
function checkpoint(){const state=historyState();if(history[cursor]&&JSON.stringify(history[cursor])===JSON.stringify(state)){updateHistoryButtons();return;}history=history.slice(0,cursor+1);history.push(state);if(history.length>80)history.shift();cursor=history.length-1;updateHistoryButtons();persist();}
function restore(){const state=history[cursor];if(!state)return;clearTimeout(timer);clearTimeout(visualRefreshTimer);stopTimelineAudition();const viewport=$('graphViewport'),position={left:viewport.scrollLeft,top:viewport.scrollTop,zoom:graphZoom},scrollY=window.scrollY;editor.innerHTML=state.html;$('storyFull').checked=state.storyFull;$('noCSS').checked=state.noCSS;$('storyTheme').value=state.storyTheme||'gray';savedRange=null;activeFontArt=null;fontRange=null;setEditable();if(originalView)$('rawDocument').textContent=editorText(editor);if(graphView){renderGraph();if(!$('soundTimelinePanel').hidden)renderSoundTimeline();else if(!visualView){applyGraphZoom(position.zoom,false);viewport.scrollLeft=position.left;viewport.scrollTop=position.top;}}if(previewView)renderPreview();updateHistoryButtons();persist();window.scrollTo(window.scrollX,scrollY);}

function setEditable(){editor.querySelectorAll('.font-art:not(.font-scatter)').forEach(art=>refreshFontLayers(art));editor.querySelectorAll('details.stack-spoiler').forEach(el=>el.open=true);editor.contentEditable='true';editor.querySelectorAll('[data-widget]').forEach(x=>x.contentEditable='false');editor.querySelectorAll('[data-editable]').forEach(x=>x.contentEditable='true');}
document.addEventListener('selectionchange',()=>{const s=getSelection();if(s.rangeCount&&!s.isCollapsed&&editor.contains(s.anchorNode)&&editor.contains(s.focusNode))savedRange=s.getRangeAt(0).cloneRange();});
document.querySelectorAll('[data-effect]').forEach(b=>b.addEventListener('mousedown',e=>e.preventDefault()));
function getRange(){if(!savedRange||!editor.contains(savedRange.commonAncestorContainer)||savedRange.collapsed){notice('请先在正文中选中要加工的文字。');return null;}const r=savedRange.cloneRange();const field=(r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement).closest('[data-field]');if(field&&['sender','recipient','option-title','branch-prompt','audio-url','track-title','track-artist','cover-url'].includes(field.dataset.field)){notice('姓名和选项标题直接编辑文字即可。');return null;}const parent=n=>n.nodeType===1?n:n.parentElement;const startSlot=parent(r.startContainer).closest('[data-editable]'),endSlot=parent(r.endContainer).closest('[data-editable]');for(const widget of editor.querySelectorAll('[data-widget]')){if(!r.intersectsNode(widget))continue;if(startSlot&&startSlot===endSlot&&widget.contains(startSlot))continue;const bounds=document.createRange();bounds.selectNode(widget);if(r.compareBoundaryPoints(Range.START_TO_START,bounds)>0||r.compareBoundaryPoints(Range.END_TO_END,bounds)<0){notice('跨越效果时，请完整选中该效果；也可以只选中效果内的正文。');return null;}}return r;}
function rangeHTML(r){const div=document.createElement('div');div.append(r.cloneContents());return div.innerHTML;}
function plainHTML(h){const d=document.createElement('div');d.innerHTML=h;d.querySelectorAll('[aria-hidden=true],.stack-spoiler>summary,button,.printer-header,.printer-trigger>summary,.printer-slot,.block-caption,.field-label,.branch-tools,.letter_cover,.letter-hint,.receipt-title,.barcode,.receipt-foot,.tear-ticket>summary,.ticket-stub,.option-btn,.step-hint').forEach(x=>x.remove());d.querySelectorAll('br').forEach(x=>x.replaceWith('\n'));d.querySelectorAll('p,div').forEach(x=>x.append('\n\n'));return d.textContent.trim().replace(/\n\s*\n/g,'\n\n');}
function page(h){return `<div class="step-text"><div class="step-inner"><div class="text-content">${slot(h)}</div></div></div>`;}
function unwrapStories(h){const temp=document.createElement('div');temp.innerHTML=h;for(const game of [...temp.querySelectorAll('.game-container')].reverse()){const body=document.createDocumentFragment();for(const content of game.querySelectorAll('.text-content > [data-editable],.effect-page-content'))for(const node of content.childNodes){if(node.nodeType===1&&node.matches('.story-step,.step-hint,.option-btn'))continue;body.append(node.cloneNode(true));}game.replaceWith(body);}return temp.innerHTML;}
function effectPage(h,next=''){return `<div class="step-text effect-page${/class="[^"]*letter-scene/.test(h)?' letter-page':''}${/class="[^"]*player-scene/.test(h)?' player-page':''}${/class="[^"]*flash-scene/.test(h)&&!/class="[^"]*attached-flash-scene/.test(h)?' flash-page':''}"><div class="step-inner"><div class="effect-page-content">${h}</div>${next?'<details class="story-step"><summary class="effect-advance" aria-label="点击空白处继续阅读"><span aria-hidden="true">&#160;</span></summary>'+next+'</details>':''}</div></div>`;}
function renderLetter(text,sender='',recipient=''){const blocks=text.split(/\n\s*\n/).filter(x=>x.trim());const groups=Array.from({length:6},()=>[]);blocks.forEach((x,i)=>groups[Math.min(5,Math.floor(i*6/Math.max(6,blocks.length)))].push(x));const names=['top','mid','bot'];const sheet=n=>names.map((name,i)=>`<div class="letter_${name}${n?2:''}"><div class="letter_${name}_text${n?2:''}">${slot(paragraphs(groups[i+n*3].join('\n\n')))}</div></div>`).join('');sender=sender.trim();recipient=recipient.trim();return wrap('letter-scene',`<div class="trifold_letter"><details class="letter-switch" open><summary class="letter_cover" aria-label="展开或收起书信">${airmailFrame()}<div class="letter_cover_stamp"></div>${sender?'<div class="letter_cover_text_top">'+esc(sender)+'</div>':''}${recipient?'<div class="letter_cover_text">'+esc(recipient)+'</div>':''}</summary></details>${sheet(0)}<div class="trifold_letter2" tabindex="0" aria-label="第二张信纸">${sheet(1)}</div></div>`);}
function renderReceipt(text){return wrap('printer-wrapper',`<div class="printer-card"><details class="printer-trigger" open><summary aria-label="轻点打印机打印或收回小票"><div class="printer-header" aria-hidden="true"><span class="printer-indicator"></span><span>THERMAL PRINTER</span></div><div class="printer-slot" aria-hidden="true"></div></summary></details><div class="receipt-window"><div class="receipt">${slot(paragraphs(text))}<div class="receipt-barcode-box"><div class="receipt-barcode-lines" aria-label="装饰条码"></div></div></div></div></div>`);}
function renderTicket(text){return wrap('train-ticket-box',`<div class="ticket-main-body"><div class="ticket-main-text">${slot(paragraphs(text))}</div></div><details class="ticket-tear-action"><summary aria-label="撕下车票副券"><div class="ticket-stub"><span>TEAR HERE</span></div></summary></details>`);}
function insert(r,html,enableStory=false){checkpoint();const parent=r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement;const root=parent.closest('[data-editable]')||editor;const fragment=r.createContextualFragment(html);const isBlock=[...fragment.childNodes].some(n=>n.nodeType===1&&/^(DIV|P|DETAILS)$/.test(n.tagName));r.deleteContents();r.collapse(true);const last=fragment.lastChild;if(isBlock){const tailRange=document.createRange();tailRange.selectNodeContents(root);tailRange.setStart(r.startContainer,r.startOffset);const tail=tailRange.extractContents();root.append(fragment);root.append(tail);root.querySelectorAll('p').forEach(p=>{if(!p.textContent.trim()&&!p.querySelector('[data-widget],br'))p.remove();});}else r.insertNode(fragment);editor.focus();const caret=document.createRange();if(last&&last.isConnected){caret.setStartAfter(last);caret.collapse(true);getSelection().removeAllRanges();getSelection().addRange(caret);}savedRange=null;if(enableStory)$('storyFull').checked=true;setEditable();checkpoint();notice('已添加编辑块。效果在下方示例区查看。');}
document.querySelectorAll('[data-effect]').forEach(b=>b.onclick=()=>{const type=b.dataset.effect;if(graphView)return applyGraphEffect(type);if(['branch','timed-branch'].includes(type)&&(!savedRange||savedRange.collapsed||!editor.contains(savedRange.commonAncestorContainer))){showView('graph');return applyGraphEffect(type);}const r=getRange();if(!r)return;const text=plainHTML(rangeHTML(r));const result=type==='letter'?letter(text):type==='receipt'?receipt(text):type==='ticket'?ticket(text):type==='journal'?journal(text):type==='player'?player(text):type==='polaroid'?polaroid(text):type==='sms'?sms(text):type==='video'?video(text):type==='image'?picture(text):type==='flash'?flash(text):type==='password'?password(text):type==='exploration'?exploration(text):type==='timed-branch'?timedBranch(text):branch(text);insert(r,result,type==='branch'||type==='timed-branch'||type==='exploration'||type==='password');if(type==='branch'){notice('分支已添加：编辑选项名称和对应剧情，在示例区体验。');}});
let fontRange=null,activeFontArt=null;
document.addEventListener('selectionchange',()=>{const selection=getSelection();if(!selection.rangeCount||selection.isCollapsed)return;const range=selection.getRangeAt(0);const parent=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;if(parent.closest('.paper-surface')||editor.contains(parent)){fontRange=range.cloneRange();activeFontArt=parent.closest('.font-art,.inline-spoiler,.inline-red-text');}});
function prepareFontEditing(root){root.querySelectorAll('details.details-inline-blur,details.inline-spoiler,details.spoiler-text').forEach(el=>el.open=true);root.querySelectorAll('[data-node-id],[data-next-id]').forEach(el=>{delete el.dataset.nodeId;delete el.dataset.nextId;});root.querySelectorAll('details.stack-spoiler').forEach(el=>el.open=true);root.querySelectorAll('.font-art').forEach(art=>{art.querySelectorAll('.chaos-row,.scatter-thread').forEach(row=>row.remove());const original=art.querySelector('.font-original');if(original){original.style.display='inline';original.contentEditable='true';}});}
function refreshFontLayers(root){if(!root?.querySelectorAll)return;[...(root.matches?.('.font-art')?[root]:[]),...root.querySelectorAll('.font-art')].forEach(art=>{const original=art.querySelector('.font-original');if(!original)return;const text=plainHTML(original.innerHTML),temp=document.createElement('div');temp.innerHTML=fontMarkup(art.classList.contains('font-dense')?'chaos':'stack',text,false,fontOptions(art));art.innerHTML=temp.firstElementChild.innerHTML;art.classList.remove('font-expanded','font-varied','font-uniform');for(const name of [...art.classList])if(name.startsWith('font-size-'))art.classList.remove(name);art.classList.add('font-scatter','font-size-18');});}
function fontOptions(art){return {packed:art?!art.classList.contains('font-airy'):$('chaosDensity').value!=='normal'};}
