$('undo').onclick=()=>{clearTimeout(timer);checkpoint();if(cursor>0){cursor--;restore();notice('已撤销。');}else notice('已经是最早的记录。');};
$('redo').onclick=()=>{clearTimeout(timer);checkpoint();if(cursor<history.length-1){cursor++;restore();notice('已重做。');}};
editor.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();}});
