function readImageFile(file){return new Promise((resolve,reject)=>{if(file.size>4*1024*1024)return reject(Error('单张图片请控制在 4 MiB 内，建议按展示尺寸压缩。'));const reader=new FileReader();reader.onerror=()=>reject(Error('图片读取失败'));reader.onload=()=>{const data=String(reader.result).split(',')[1],bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));let type='';if(bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71)type='image/png';else if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255)type='image/jpeg';else if(String.fromCharCode(...bytes.slice(0,6)).match(/^GIF8[79]a$/))type='image/gif';else if(String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP')type='image/webp';if(!type)return reject(Error('请选择 JPG、PNG、GIF 或 WebP 图片。'));const image=new Image();image.onload=()=>{if(!image.naturalWidth||image.naturalWidth*image.naturalHeight>32000000)return reject(Error('图片尺寸过大，请缩小后再导入'));resolve({name:file.name,type,data});};image.onerror=()=>reject(Error('图片损坏或当前浏览器无法读取'));image.src='data:'+type+';base64,'+data;};reader.readAsDataURL(file);});}
