const recordPlayerCSS="/* Interactive controls are only included in script-enabled readers and ZIPs. */\n.record-player .record-controls{color:#111}\n.record-button{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;padding:6px;border:0;border-radius:50%;background:transparent;color:#080808;cursor:pointer;box-sizing:border-box}\n.record-button svg{width:24px;height:24px;display:block;overflow:visible}\n.record-button:focus{outline:2px solid #777;outline-offset:2px}.record-button:disabled{opacity:.25;cursor:default}.record-button[aria-pressed=true]{background:#ededed}.record-reactions .record-button[aria-pressed=true] svg{fill:#111}\n.record-reactions,.record-transport,.record-volume,.record-times{display:flex;align-items:center;justify-content:space-between}\n.record-reactions{margin:6px 0 12px}.record-reactions .record-button{width:30px;height:30px;padding:3px}\n.record-timeline{position:relative;height:20px;margin:0 2px}.record-timeline:before{content:\"\";position:absolute;top:8px;left:0;right:0;height:4px;background:#999;border-radius:4px}.record-progress-fill{position:absolute;left:0;top:8px;height:4px;background:#000;border-radius:4px;pointer-events:none}\n.record-controls input[type=range]{-webkit-appearance:none;appearance:none;display:block;min-width:0;height:20px;padding:0;border:0;outline-offset:2px;background:transparent;cursor:pointer;box-sizing:border-box}\n.record-timeline input{position:relative;width:100%;margin:0}.record-controls input[type=range]::-webkit-slider-runnable-track{height:4px;background:transparent;border:0}.record-controls input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:12px;height:12px;margin-top:-4px;border:0;border-radius:50%;background:#000}.record-controls input[type=range]::-moz-range-track{height:4px;background:#999;border:0}.record-controls input[type=range]::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:#000}\n.record-times{font:11px/1.6 Arial,sans-serif;color:#999;margin:0 2px 6px}.record-transport{margin:4px 0 12px}.record-transport .record-primary{width:50px;height:50px}.record-primary svg{width:37px;height:37px}\n.record-volume .record-button{width:28px;height:28px;padding:4px}.record-volume input{flex:1;width:60%;margin:0 12px;background:#999;height:4px;border-radius:4px}.record-controls .record-volume input[type=range]{height:4px;background:#999}.record-controls .record-volume input[type=range]::-webkit-slider-runnable-track{background:#999}\n.record-playlist{margin-top:14px;border-top:1px solid #eee;padding-top:6px;max-height:140px;overflow-y:auto}.record-playlist[hidden]{display:none}.record-playlist button{display:block;width:100%;padding:8px;border:0;background:transparent;color:#333;text-align:left;font:12px/1.5 sans-serif;cursor:pointer}.record-playlist button[aria-pressed=true]{background:#eee;border-radius:4px}\n.record-status:empty{display:none}.record-status{font:11px/1.6 sans-serif;color:#9a3636;margin:8px 0 0}\n.record-mini{display:flex;align-items:center;justify-content:space-between;width:280px;max-width:calc(100% - 24px);left:50%;right:auto;transform:translateX(-50%);bottom:12px;border:1px solid #ddd;border-radius:30px;background:#fff;padding:6px 10px;box-shadow:0 3px 20px rgba(0,0,0,.12)}.record-mini[hidden]{display:none}.record-mini audio{display:none}.record-mini span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:12px/1.5 sans-serif;margin:0 8px}.record-mini .record-button{width:30px;height:30px;padding:5px}\n@keyframes paper-record-spin{to{transform:rotate(360deg)}}\n#workskin .record-vinyl{animation:paper-record-spin 18s linear infinite;animation-play-state:paused}\n#workskin .record-arm{transition:transform .85s ease-in-out}\n#workskin .record-player.is-playing .record-vinyl{animation-play-state:running}\n#workskin .record-player.is-engaged .record-arm{transform:rotate(1deg)}\n@media(prefers-reduced-motion:reduce){#workskin .record-vinyl{animation:none}#workskin .record-arm{transition:none}}\n";
const recordMiniVolumeCSS='.record-mini .record-mini-volume{display:flex;align-items:center;flex:0 0 auto;margin:0 4px}.record-mini .record-mini-volume .record-button{width:24px;height:24px;padding:3px}.record-mini .record-mini-volume svg{width:18px;height:18px}.record-mini .record-mini-volume input{display:block;box-sizing:border-box;width:58px;min-width:0;height:20px;margin:0 2px;padding:0;cursor:pointer}.record-mini>span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}';
function standaloneArticle(markup){for(const [key,url] of musicObjectURLs){const asset=musicAssets[key];if(asset)markup=markup.split(esc(url)).join('data:'+asset.type+';base64,'+asset.data);}return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>小说作品</title><style>body{margin:0;padding:0;font:16px/1.8 Georgia,serif}'+css+'#workskin .game-container{margin:0;height:100vh}#workskin .game-container .step-text,#workskin .game-container .fork-container{height:100vh}'+readerContentFitCSS+articleAudioCSS+recordPlayerCSS+recordMiniVolumeCSS+screenFlashCSS+timedChoicesCSS+pageSoundCSS+(markup.includes('class="book-reader"')?bookReaderCSS+minitoolLetterCSS:'')+'/* Editor preview only: hide scrollbars without disabling scrolling. */*{scrollbar-width:none;-ms-overflow-style:none}*::-webkit-scrollbar{display:none;width:0;height:0}</style></head><body>'+markup+articleAudioScript()+'</body></html>';}
function receipt(text){return editBlock('receipt','打印小票',editBody(paragraphs(text)));}
function ticket(text){return editBlock('ticket','撕拉票根',editBody(paragraphs(text)));}
function journal(text){return editBlock('journal','日记本',`<div class="document-pages">${editBody(paragraphs(text),'page-body')}${editBody('','page-body')}</div>`);}
function documentPages(html){return `<div class="document-pages">${editBody(html,'page-body')}</div>`;}
const activePages=new WeakMap();
function pageFields(source){return [...source.querySelector('.document-pages').children];}
function renderJournal(parts){return renderJournalPages([parts]);}
function renderJournalPages(pages){const spread=i=>`<div class="journal-spread"><div class="journal-page journal-page-left"><div class="journal-header">${i+1}</div>${partsHTML(pages[i]||[])}</div><div class="journal-page journal-page-right"><div class="journal-header">${i+2}</div>${partsHTML(pages[i+1]||[])}</div></div>`;let body=spread(Math.floor((pages.length-1)/2)*2);for(let i=Math.floor((pages.length-1)/2)*2-2;i>=0;i-=2)body=spread(i)+`<details class="journal-turn"><summary><span class="turn-next">下一页 →</span><span class="turn-back">← 上一页</span></summary><div class="journal-next">${body}</div></details>`;return wrap('journal-scene',`<details class="journal-wrapper"><summary aria-label="打开或合上日记本"><div class="journal-cover"><span class="journal-cover-title">JOURNAL</span></div><span class="journal-close">合上日记</span></summary></details><div class="journal-base">${body}</div>`);}
function paperSurface(field,index,kind){const area=document.createElement('div');area.className='paper-surface '+kind;area.contentEditable='true';area.dataset.graphField=kind==='letter-paper'?'letter-face':'page-body';area.dataset.pageIndex=index;area.setAttribute('role','textbox');area.setAttribute('aria-multiline','true');area.setAttribute('aria-label',(kind==='letter-paper'?'信纸':'日记')+'第 '+(index+1)+' 页');area.dataset.placeholder='点击纸面编辑…';area.innerHTML=field.innerHTML;prepareFontEditing(area);return area;}
function ensureLetterFaces(source){const body=source.querySelector('[data-field=body]');if(body.querySelector('.letter-faces'))return;const parts=renderParts(body),groups=Array.from({length:6},()=>[]);parts.forEach((part,i)=>groups[Math.min(5,Math.floor(i*6/Math.max(6,parts.length)))].push(part));body.innerHTML='<div class="letter-faces">'+groups.map(group=>editBody(partsHTML(group),'letter-face')).join('')+'</div>';}
function renderLetterAuthor(source){const fields=[...source.querySelectorAll('[data-field=letter-face]')];if(!fields.length)return renderLetterParts(renderParts(source.querySelector('[data-field=body]')),fieldText(source,'sender'),fieldText(source,'recipient'));const temp=document.createElement('div');temp.innerHTML=renderLetter('',fieldText(source,'sender'),fieldText(source,'recipient'));[...temp.querySelectorAll('[data-editable]')].forEach((face,i)=>face.innerHTML=partsHTML(renderParts(fields[i]))||'<p><br></p>');return temp.innerHTML;}
function letterPaperEditor(source,fields){ensureLetterFaces(source);fields.classList.add('letter-direct');const papers=document.createElement('div');papers.className='letter-paper-spread';[...source.querySelectorAll('[data-field=letter-face]')].forEach((field,i)=>papers.append(paperSurface(field,i,'letter-paper')));fields.append(papers);}
function pageEditor(source,fields){const pages=pageFields(source),index=Math.floor(Math.min(activePages.get(source)||0,pages.length-1)/2)*2;activePages.set(source,index);fields.classList.add('notebook-direct');const controls=document.createElement('div');controls.className='page-controls';controls.innerHTML=`<button data-graph-action="page-prev" ${index===0?'disabled':''}>←</button><span>第 ${index+1}${pages[index+1]?'–'+(index+2):''} / ${pages.length} 页</span><button data-graph-action="page-next" ${index+2>=pages.length?'disabled':''}>→</button><button data-graph-action="page-add">＋ 页</button>`;fields.append(controls);const spread=document.createElement('div');spread.className='notebook-paper-spread';for(let i=index;i<index+2;i++){if(pages[i])spread.append(paperSurface(pages[i],i,'journal-paper'));else{const blank=document.createElement('div');blank.className='paper-blank';spread.append(blank);}}fields.append(spread);}


function nextOptionTitle(options){const names=new Set([...options.children].map(o=>fieldText(o,'option-title')));let n=1;while(names.has('选项 '+n))n++;return '选项 '+n;}
function optionEditor(title,text,ending=false){return `<div class="branch-option" data-ending="${ending}"><div class="option-heading"><span class="edit-field" data-field="option-title" data-editable="true" contenteditable="true">${esc(title)}</span><button class="ending-button" data-action="toggle-ending" title="切换是否接回共同后文">${ending?'独立结局':'接回后文'}</button><button data-action="remove-option" aria-label="删除此选项">×</button></div>${editBody(paragraphs(text),'option-body')}</div>`;}
function branch(text){return editBlock('branch','剧情分支',`${editBody(paragraphs(text),'branch-prompt')}<div data-field="options">${optionEditor('选项 1','')}${optionEditor('选项 2','')}</div><div class="branch-tools"><button data-action="add-option">＋ 添加选项</button></div>`);}
function editorText(root){const copy=root.cloneNode(true);copy.querySelectorAll('.block-caption,.field-label,.branch-tools,.player-fields,.sms-author-settings,.sms-message-meta,button').forEach(x=>x.remove());copy.querySelectorAll('.inline-field').forEach(x=>x.append('\n'));return plainHTML(copy.innerHTML);}
function migrateEditor(markup){const temp=document.createElement('div');temp.innerHTML=markup;const interactive=!!temp.querySelector('.game-container');temp.innerHTML=unwrapStories(temp.innerHTML);for(const old of [...temp.querySelectorAll('.letter-scene')]){const sender=old.querySelector('.letter_cover_text_top')?.textContent.trim()||'',recipient=old.querySelector('.letter_cover_text')?.textContent.trim()||'';const body=[...old.querySelectorAll('.letter_top_text,.letter_mid_text,.letter_bot_text,.letter_top_text2,.letter_mid_text2,.letter_bot_text2')].map(x=>plainHTML(x.innerHTML)).filter(Boolean).join('\n\n');old.outerHTML=letter(body,sender,recipient);}for(const old of [...temp.querySelectorAll('.printer-wrapper')])old.outerHTML=receipt(plainHTML(old.outerHTML));for(const old of [...temp.querySelectorAll('.receipt')])old.outerHTML=receipt(plainHTML(old.outerHTML));for(const old of [...temp.querySelectorAll('.train-ticket-box,.ticket-wrapper')])old.outerHTML=ticket(plainHTML(old.outerHTML));for(const option of temp.querySelectorAll('.branch-option'))setOptionEnding(option,option.dataset.ending==='true');for(const block of temp.querySelectorAll('.edit-block[data-widget=journal]')){if(block.querySelector('.document-pages'))continue;const body=block.querySelector('[data-field=body]');if(body)body.outerHTML=documentPages(body.innerHTML);}for(const block of temp.querySelectorAll('.edit-block[data-widget=letter]')){const pages=block.querySelector('.document-pages');if(pages)pages.outerHTML=editBody([...pages.children].map(page=>page.innerHTML).join(''));}for(const block of temp.querySelectorAll('.edit-block:not([data-widget=branch])'))if(!block.querySelector(':scope > [data-field=after-text]'))block.insertAdjacentHTML('beforeend',afterTextField());return {html:temp.innerHTML,interactive};}
function fieldText(block,name){return block.querySelector('[data-field="'+name+'"]')?.textContent.trim()||'';}
function renderParts(root){if(!root)return [];const parts=[];let inline='';const flush=()=>{if(inline.trim())parts.push({html:inline,effect:false});inline='';};function visit(node){if(node.nodeType===3){inline+=esc(node.textContent);return;}if(node.nodeType!==1)return;if(node.matches('.edit-block')){flush();const type=node.dataset.widget,body=node.querySelector('[data-field=body]');if(type==='password')parts.push({html:renderPassword(node),effect:true,gate:true});else if(type==='polaroid')parts.push({html:renderPolaroid(node),effect:true});else if(type==='sms')parts.push({html:renderSMS(node),effect:true});else if(type==='letter')parts.push({html:renderLetterAuthor(node),effect:true});else if(type==='video')parts.push({html:renderVideo(node),effect:true});else if(type==='flash')parts.push({html:renderFlash(node),effect:true});else if(type==='image')parts.push({html:renderPicture(node),effect:true});else if(type==='player')parts.push({html:renderPlayer(node),effect:true});else if(type==='receipt')parts.push({html:renderBodyParts('receipt',renderParts(body)),effect:true});else if(type==='ticket')parts.push({html:renderBodyParts('ticket',renderParts(body),node),effect:true});else if(type==='journal')parts.push({html:renderJournalPages(pageFields(node).map(renderParts)),effect:true});else if(type==='branch'){const prompt=node.querySelector('[data-field=branch-prompt]');const options=node.querySelector('[data-field=options]');parts.push({branch:{timed:node.dataset.storyTimed==='yes',timedSeconds:timedSeconds(node),timeout:node.dataset.storyTimeout||'',timedKey:node.dataset.nodeId,explore:node.dataset.storyExplore==='yes',exploreId:node.dataset.nodeId,storyAuto:node.dataset.storyAuto,prompt:prompt?renderParts(prompt).map(x=>x.html||'').join(''):'',options:[...(options?.children||[])].filter(x=>x.matches('.branch-option')).map((o,i)=>({nodeId:o.dataset.nodeId,nextId:o.dataset.nextId,label:fieldText(o,'option-title')||'选项 '+(i+1),...choiceLabelParts(o.querySelector('[data-field=option-title]')),ending:o.dataset.ending==='true',storySet:o.dataset.storySet,storyAction:o.dataset.storyAction,storyRequire:o.dataset.storyRequire,storyWhen:o.dataset.storyWhen,parts:renderParts(o.querySelector('[data-field=option-body]'))}))}});}if(node.dataset.pageFlash==='yes'&&parts.at(-1)?.effect){const part=parts.at(-1);if(imageTarget==='ao3'){const gif=imageLink(fieldText(node,'flash-gif-url'));if(!gif)throw Error('书信/日记已添加屏闪：AO3 需填写单次 GIF 直链；小红书无需 GIF。');part.html='<div class="attached-flash-scene"><img class="flash-ao3-gif" src="'+esc(gif)+'" alt="屏闪">'+part.html+'</div>';}else{const color=flashColor(node),url=localImageURL(node)||imageLink(fieldText(node,'image-url'));part.html='<div class="attached-flash-scene flash-enabled flash-'+color+' flash-wait-'+flashDelay(node)+' flash-duration-'+flashDuration(node)+'">'+(url?'<img class="flash-optional-image" width="'+flashImageWidth(node)+'%" src="'+esc(url)+'" alt="">':'')+flashCopyMarkup(node)+part.html+'</div>';}}if(parts.at(-1)){parts.at(-1).nodeId=node.dataset.nodeId;parts.at(-1).nextId=node.dataset.nextId;parts.at(-1).storyEnd=node.dataset.storyEnd==='yes';parts.at(-1).storyReturn=node.dataset.storyReturn||'';parts.at(-1).endingId=node.dataset.endingId||'';}const after=node.querySelector(':scope > [data-field=after-text]');if(type!=='branch'&&after&&after.textContent.trim()&&parts.at(-1)?.effect)parts.at(-1).html+='<div class="effect-after-text">'+partsHTML(renderParts(after))+'</div>';return;}if(node.querySelector('.edit-block')){flush();for(const child of node.childNodes)visit(child);flush();}else if(/^(P|DIV)$/.test(node.tagName)||node.dataset.nodeId){flush();if(node.textContent.trim()||node.dataset.nodeId)parts.push({html:node.outerHTML,effect:false,nodeId:node.dataset.nodeId,nextId:node.dataset.nextId,storyEnd:node.dataset.storyEnd==='yes',storyReturn:node.dataset.storyReturn||'',endingId:node.dataset.endingId||''});}else inline+=node.outerHTML;}for(const node of root.childNodes)visit(node);flush();if(imageTarget!=='ao3')for(const part of parts){const source=part.nodeId&&Array.from(root.querySelectorAll('[data-node-id]')).find(el=>el.dataset.nodeId===part.nodeId);if(!source||!source.dataset.soundUrl&&source.dataset.soundMode!=='stop')continue;const mode=['start','stop'].includes(source.dataset.soundMode)?source.dataset.soundMode:'page';let audio='';if(mode!=='stop'){const url=mediaURL(source.dataset.soundUrl);if(!url)throw Error('页面音效已失效，请重新选择音频。');audio='<audio class="page-sound-audio sound-volume-'+Math.max(0,Math.min(100,Number(source.dataset.soundVolume)||0))+'" preload="none" src="'+esc(url)+'"></audio>';}const open='<div class="page-sound-scene sound-mode-'+mode+(mode==='start'&&source.dataset.soundLoop!=='no'?' sound-loop':'')+'" data-sound-key="'+esc(source.dataset.nodeId)+'">';if(part.branch)part.branch.prompt=open+audio+part.branch.prompt+'</div>';else part.html=open+audio+part.html+'</div>';}if(imageTarget!=='ao3')decorateSoundTimeline(parts,root);decoratePageLayouts(parts,root);return parts;}
function partsHTML(parts){return parts.map(item=>item.branch?wrap('game-container',renderBranch(item.branch)):item.storyEnd?renderEndingPage(item):item.html).join('');}
function renderLetterParts(parts,sender,recipient){const temp=document.createElement('div');temp.innerHTML=renderLetter('',sender,recipient);const faces=[...temp.querySelectorAll('[data-editable]')];const groups=Array.from({length:6},()=>[]);parts.forEach((item,i)=>groups[Math.min(5,Math.floor(i*6/Math.max(6,parts.length)))].push(item));faces.forEach((face,i)=>face.innerHTML=partsHTML(groups[i])||'<p><br></p>');return temp.innerHTML;}
function renderBodyParts(type,parts,source=null){const temp=document.createElement('div');temp.innerHTML=type==='receipt'?renderReceipt(''):source&&fieldText(source,'ticket-theme')==='red'?renderRedTicket(source):renderTicket('');temp.querySelector('[data-editable]').innerHTML=partsHTML(parts)||'<p><br></p>';return temp.innerHTML;}
function renderBranch(branch,next=''){if(branch.explore)return renderExploreBranch(branch,next);return renderChoiceBranch(branch,option=>composeSteps(option.parts,option.ending?'':next));}
function composeSteps(parts,next=''){let tail=next;for(const item of [...parts].reverse()){if(item.branch)tail=renderBranch(item.branch,tail);else if(item.gate)tail=renderPasswordPage(item,item.storyEnd?renderEndingPage({...item,html:'',effect:false}):tail);else if(item.storyEnd)tail=renderEndingPage(item);else if(item.effect)tail=effectPage(item.html,tail);else if(tail)tail=`<details class="story-step"><summary>${page(item.html)}<span class="step-hint">点击本页空白处，继续阅读 →</span></summary>${tail}</details>`;else tail=page(item.html);}return tail||page('<p></p>');}
function fontFitSize(text,width,height){const lines=text.split(/\n+/).filter(Boolean);for(let size=32;size>=2;size--){const columns=Math.max(1,Math.floor(width/(size*1.7)));const rows=lines.reduce((sum,line)=>sum+Math.max(1,Math.ceil(Array.from(line).reduce((n,c)=>n+(/[^\x00-\xff]/.test(c)?1:0.6),0)/columns)),0);if(rows*size*1.7*1.15+lines.length*size<=height)return size;}return 2;}
function fitFontArt(root){root.querySelectorAll('.font-art').forEach(art=>{const original=art.querySelector('.font-original');if(!original)return;const paper=art.closest('.letter_top_text,.letter_mid_text,.letter_bot_text,.letter_top_text2,.letter_mid_text2,.letter_bot_text2'),journal=art.closest('.journal-page'),container=paper||journal,text=art.closest('.text-content');let height=400;if(container){const copy=container.cloneNode(true);copy.querySelectorAll('.font-art,summary').forEach(el=>el.remove());const rest=plainHTML(copy.innerHTML).replace(/\s/g,'').length;const available=(paper?140:150)-Math.ceil(rest/(paper?10:8))*(paper?18:14);height=Math.max(24,Math.min(paper?136:144,Math.floor(available/8)*8));}else if(text){const copy=text.cloneNode(true);copy.querySelectorAll('.font-art,summary').forEach(el=>el.remove());if(!plainHTML(copy.innerHTML).trim()){height=600;art.classList.add('font-page-fill');text.classList.add('font-page-text');}}for(const name of [...art.classList])if(name.startsWith('font-size-')||name.startsWith('font-height-')||name==='font-expanded'||name==='font-uniform'||name==='font-varied')art.classList.remove(name);art.classList.add('font-scatter','font-size-'+(container?Math.max(2,Math.floor(height/600*18)):18));if(container)art.classList.add('font-in-paper','font-height-'+height);});}

function renderHTML(target='preview',startId=''){const previous=imageTarget;imageTarget=target;try{graphProjection(editor);validateTimedBranches();if(target!=='ao3')validateSoundTimeline();refreshFontLayers(editor);const parts=renderParts(editor);const gates=editor.querySelectorAll('[data-widget=password]');if(gates.length)$('storyFull').checked=true;if(target!=='preview')for(const gate of gates){if(!fieldText(gate,'password-answer').trim())throw Error('密码关卡尚未填写正确答案。');const parent=gate.parentElement.closest('[data-widget]');if(parent&&parent.dataset.widget!=='branch')throw Error('密码关卡请单独作为剧情页面，勿嵌入信纸或其他物件。');}const hasConnections=!!editor.querySelector('[data-next-id]');if(hasConnections)$('storyFull').checked=true;if(target==='ao3'){const graph=indexStoryGraph(parts);if(estimateStoryGraph(graph.nodes,graph.start)>500000)throw Error('当前章分支展开预计超过 50 万 HTML 字符预检阈值，请拆分本章；其他章节可独立导出。');}const useNodes=target!=='ao3'&&($('storyFull').checked||hasConnections||startId);let markup=useNodes?wrap('game-container',renderNodeStory(parts,startId)):(hasConnections||target==='preview'&&startId)?wrap('game-container',compileConnectedStory(parts,startId)):$('storyFull').checked?wrap('game-container',composeSteps(parts)):parts.map(item=>item.branch?wrap('game-container',renderBranch(item.branch)):item.storyEnd?renderEndingPage(item):item.html).join('');const temp=document.createElement('div');temp.innerHTML=markup;temp.querySelectorAll('.game-container').forEach(game=>game.classList.add('theme-'+($('storyTheme').value||'gray')));resolvePageLayouts(temp);fitFontArt(temp);if(target==='ao3')temp.querySelectorAll('div[data-editable=true]').forEach(el=>{if(el.childNodes.length===1&&el.firstElementChild?.matches('p,div')&&Array.from(el.attributes).every(a=>['data-editable','contenteditable'].includes(a.name)))el.replaceWith(...el.childNodes);});temp.querySelectorAll('*').forEach(el=>{for(const a of [...el.attributes])if(a.name.startsWith('data-')&&!(target!=='ao3'&&/^(?:data-story-(?:set|action|require|when|auto)|data-explore-(?:group|route)|data-timed-(?:key|seconds|timeout|choice)|data-sound-key|data-timeline-(?:page|track|config)|data-ending-(?:key|label)|data-password-(?:key|answer|case|error)|data-node-(?:root|start|key|target|group|route))$/.test(a.name))||a.name==='contenteditable')el.removeAttribute(a.name);el.classList.remove('widget');if(!el.className)el.removeAttribute('class');if(target==='ao3')el.classList.remove('flash-return-front');if(el.tagName==='DETAILS')el.removeAttribute('open');});const result='<div id="workskin">'+(target==='ao3'&&parts.some(part=>part.storyEnd||part.branch)?'<a id="paper-story-start"></a>':'')+temp.innerHTML+'</div>';if(target==='ao3'&&result.length>500000)throw Error('当前章实际 HTML 超过 50 万字符预检阈值，请拆分本章后再导出。');return result;}finally{imageTarget=previous;}}
