function indexStoryGraph(parts){
 const nodes=new Map();let serial=0;
 function index(list,continuation=''){let next=continuation;for(const part of [...list].reverse()){
 const id=part.nodeId||'internal-'+serial++;if(nodes.has(id))throw Error('存在重复节点，请撤销复制的节点或重新导入草稿。');
 if(part.branch){const choices=part.branch.options.map(option=>{const choiceId=option.nodeId||'internal-'+serial++;let after=option.ending?'':next;if(part.branch.explore){after='explore-return-'+serial++;nodes.set(after,{kind:'exploreReturn',group:id,route:choiceId});}nodes.set(choiceId,{kind:'choice',next:index(option.parts,after),override:option.nextId});return {...option,id:choiceId};});nodes.set(id,{kind:'branch',branch:part.branch,prompt:part.branch.prompt,storyAuto:part.branch.storyAuto,choices,next});}
 else nodes.set(id,{kind:'page',part,next,override:part.nextId});next=id;}return next;}
 return {nodes,start:index(parts)};
}
function compileConnectedStory(parts,startId=''){
 const {nodes,start}=indexStoryGraph(parts),cache=new Map();if(imageTarget==='ao3'&&estimateStoryGraph(nodes,startId&&nodes.has(startId)?startId:start)>500000)throw Error('当前章的分支展开预计超过纸间的 50 万 HTML 字符预检阈值，请在章节管理中拆分这一章；其他章节可独立导出。');
 function compile(id,trail=new Set()){if(!id||id==='__end__')return '';if(trail.has(id))throw Error('连线形成循环，请断开回跳连线；需要反复探索时请使用探索分支。');if(trail.size>250)throw Error('路线过长，请分章生成。');if(cache.has(id))return cache.get(id);const node=nodes.get(id);if(!node)throw Error('有一条连线的目标已不存在，请在工作台重新连接。');const nextTrail=new Set(trail);nextTrail.add(id);let result;
 if(node.kind==='exploreReturn')result=explorationReturnPage();
 else if(node.kind==='choice')result=compile(node.override===undefined?node.next:node.override,nextTrail);
 else if(node.kind==='branch'&&node.branch.explore)result=renderExploreBranch(node.branch,compile(node.next,nextTrail),node.choices.map(choice=>compile(choice.id,nextTrail)));
 else if(node.kind==='branch')result=renderChoiceBranch({...node.branch,prompt:node.prompt,options:node.choices},choice=>compile(choice.id,nextTrail));
 else{const next=node.part.storyEnd?'':compile(node.override===undefined?node.next:node.override,nextTrail);result=node.part.gate?renderPasswordPage(node.part,node.part.storyEnd?renderEndingPage({...node.part,html:'',effect:false}):next):node.part.storyEnd?renderEndingPage(node.part):node.part.effect?effectPage(node.part.html,next):next?`<details class="story-step"><summary>${page(node.part.html)}<span class="step-hint">点击本页空白处，继续阅读 →</span></summary>${next}</details>`:page(node.part.html);}
 if(result.length>8000000)throw Error('分支展开后的代码过大，请拆分章节。');cache.set(id,result);return result;}
 return compile(startId&&nodes.has(startId)?startId:start)||page('<p></p>');
}
let pendingConnection=null,selectedConnection=null,dragConnection=null;
function applyConnectionEdges(layout){const byKey=new Map(layout.nodes.map(node=>[node.key,node]));layout.edges=layout.edges.filter(edge=>edge.from.nextId===undefined&&edge.from.source?.dataset.storyEnd!=='yes');for(const node of layout.nodes){if(node.source?.dataset.storyEnd==='yes'){node.routeEnd=true;continue;}if(node.nextId&&node.nextId!=='__end__'){const target=byKey.get(node.nextId);if(target)layout.edges.push({from:node,to:target,custom:true,join:true});}if(node.nextId!==undefined)node.routeEnd=node.nextId==='__end__';}const reached=new Set();function visit(node){if(!node||reached.has(node.id))return;reached.add(node.id);for(const edge of layout.edges)if(edge.from===node)visit(edge.to);}visit(layout.nodes[0]);for(const node of layout.nodes)node.unreachable=!reached.has(node.id);}
function validateConnection(from,to){if(!from||!to)return '请选择有效节点。';if(from===to)return '不能连接节点自身。';if(from.kind==='branch')return '分支节点通过选项出发，请连接选项或其后续节点。';if(to.kind==='choice')return '请选择剧情正文、效果或分支节点作为目标。';if(to.order<=from.order)return '第一版仅支持向后连接，避免循环和回跳。';return '';}
function connectNodes(fromId,toId){const from=graphNodes.get(fromId),to=graphNodes.get(toId),error=validateConnection(from,to);if(error)return notice(error);checkpoint();from.source.dataset.nextId=to.key;$('storyFull').checked=true;pendingConnection=null;selectedConnection=null;checkpoint();renderGraph(from.source);notice('连线已保存：此路线将接到目标节点，原有正文仍保留。');}
function selectConnection(fromId,toId){const from=graphNodes.get(fromId);if(from?.kind==='branch')return notice('分支到选项的连线属于选项结构；修改选项即可调整。');selectedConnection={fromId,toId};pendingConnection=null;updateConnectionBar();}
function updateConnectionBar(){const origin=graphNodes.get(pendingConnection);for(const card of $('graphStage').querySelectorAll('.graph-card')){const node=graphNodes.get(card.dataset.graphId);card.classList.toggle('link-ready',!!origin&&!validateConnection(origin,node));card.classList.toggle('link-origin',node===origin);}const bar=$('connectionBar');if(!bar)return;bar.hidden=!selectedConnection&&!pendingConnection;for(const line of $('graphStage').querySelectorAll('.connection-line'))line.classList.toggle('selected-line',selectedConnection?.fromId===line.dataset.from&&selectedConnection?.toId===line.dataset.to);if(selectedConnection){const from=graphNodes.get(selectedConnection.fromId),to=graphNodes.get(selectedConnection.toId);$('connectionLabel').textContent='连线：'+(from?.label||'节点')+' → '+(to?.label||'节点');}else if(pendingConnection)$('connectionLabel').textContent='请选择目标节点上方的圆点；按 Esc 取消。';$('disconnectEdge').hidden=!selectedConnection;$('resetEdge').hidden=!selectedConnection;}
function addConnectionPorts(card,item){const input=document.createElement('button');input.className='graph-port port-in';input.type='button';input.setAttribute('aria-label','连接到此节点');input.title='连线入口';input.textContent='';input.disabled=item.kind==='choice';input.addEventListener('click',e=>{e.stopPropagation();if(pendingConnection)connectNodes(pendingConnection,item.id);else notice('先点击起点下方的圆点。');});input.addEventListener('dragover',e=>{if(dragConnection){e.preventDefault();e.dataTransfer.dropEffect='link';}});input.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();if(dragConnection)connectNodes(dragConnection,item.id);dragConnection=null;});card.append(input);if(item.kind==='branch')return;const output=document.createElement('button');output.type='button';output.className='graph-port port-out';output.setAttribute('aria-label','从此节点连线');output.title='拖到目标入口，或点击后选择目标';output.draggable=false;output.addEventListener('pointerdown',e=>beginPortDrag(e,item.id));output.addEventListener('click',e=>{e.stopPropagation();if(suppressPortClick){suppressPortClick=false;return;}pendingConnection=pendingConnection===item.id?null:item.id;selectedConnection=null;updateConnectionBar();notice(pendingConnection?'再点击目标节点上方的圆点，即可连接。':'已取消连线。');});card.append(output);}
function disconnectSelected(reset=false){const item=graphNodes.get(selectedConnection?.fromId);if(!item)return;checkpoint();if(reset)delete item.source.dataset.nextId;else item.source.dataset.nextId='__end__';selectedConnection=null;checkpoint();renderGraph(item.source);notice(reset?'已恢复文档顺序中的默认连线。':'连线已断开，节点正文保留；此路线在这里结束。');}
