 if(['letter','journal'].includes(type)&&source.dataset.pageFlash!=='yes'){const addFlash=document.createElement('button');addFlash.type='button';addFlash.textContent='添加屏闪（保留当前纸张与文字）';addFlash.onclick=()=>{source.dataset.pageFlash='yes';ensureAttachedFlashFields(source);checkpoint();renderGraph(source);notice('已添加本页屏闪，设置在右侧。');};settings.append(addFlash);}if(source.dataset.pageFlash==='yes'){const title=document.createElement('strong');title.textContent='已添加：屏闪';settings.append(title);appendFlashFields(settings,source);const remove=document.createElement('button');remove.textContent='移除本页屏闪';remove.onclick=()=>{source.dataset.pageFlash='no';checkpoint();renderGraph(source);};settings.append(remove);}if(type==='password')appendPasswordFields(settings,source);if(type==='ticket')appendTicketFields(settings,source);if(type==='image')appendImageFields(settings,source);if(type==='polaroid')appendPolaroidFields(settings,source);if(type==='flash')appendFlashFields(settings,source);if(type==='video')appendVideoFields(settings,source);
