function workspaceRecord(){const record=documentRecord();if(book)workLibrary.set(book.id,record);return {...record,library:{version:1,documents:[...workLibrary.values()].filter(doc=>doc.book&&doc.book.id!==book.id)}};}
function validWorkRecord(record){return record&&record.format==='paper-studio'&&record.version===1&&typeof record.html==='string'&&record.book&&typeof record.book.id==='string'&&Array.isArray(record.book.chapters)&&record.book.chapters.length>0&&record.book.chapters.every(c=>c&&typeof c.id==='string'&&typeof c.html==='string');}
