function switchWork(id){if(!workLibrary.has(id)||id===book.id)return;checkpoint();const record=workLibrary.get(id);try{loadDocument(record,true);}catch(error){paintWorks();notice('切换未完成，当前正文已保留：'+error.message);}}
$('workSelect').addEventListener('change',()=>switchWork($('workSelect').value));
$('newWork').onclick=()=>{checkpoint();const id=newChapterId(),chapterId=newChapterId(),settings={storyFull:false,noCSS:true,storyTheme:'gray'},html='<p><br></p>';loadDocument({format:'paper-studio',version:1,editorVersion:3,savedAt:new Date().toISOString(),html,assets:{},images:{},settings,book:{id,title:'未命名作品 '+(workLibrary.size+1),active:chapterId,chapters:[{id:chapterId,title:'第一章',html,settings}]}},true);};
