let portDrag=null,suppressPortClick=false;
function beginPortDrag(event,id){if(event.pointerType==='mouse'&&event.button!==0)return;event.preventDefault();event.stopPropagation();portDrag={id,startX:event.clientX,startY:event.clientY,moved:false,port:event.currentTarget,pointerId:event.pointerId};event.currentTarget.setPointerCapture(event.pointerId);}
document.addEventListener('pointermove',event=>{if(!portDrag)return;if(Math.hypot(event.clientX-portDrag.startX,event.clientY-portDrag.startY)<4&&!portDrag.moved)return;portDrag.moved=true;pendingConnection=portDrag.id;selectedConnection=null;updateConnectionBar();const item=graphNodes.get(portDrag.id),svg=$('graphStage').querySelector('svg');if(!item||!svg)return;const target=findSnapTarget(event.clientX,event.clientY,portDrag.id);showSnapTarget(target);let path=svg.querySelector('.draft-connection');if(!path){path=document.createElementNS('http://www.w3.org/2000/svg','path');path.classList.add('draft-connection');svg.append(path);}const rect=$('graphStage').getBoundingClientRect(),x=(event.clientX-rect.left)/graphZoom,y=(event.clientY-rect.top)/graphZoom;path.setAttribute('d',target?connectionCurve(item,target):`M${item.x+GRAPH_WIDTH/2} ${item.y+item.height+14*Math.min(2,1/graphZoom)} L${x} ${y}`);});
document.addEventListener('pointerup',event=>{if(!portDrag)return;const drag=portDrag;portDrag=null;if(drag.port.hasPointerCapture(drag.pointerId))drag.port.releasePointerCapture(drag.pointerId);$('graphStage').querySelector('.draft-connection')?.remove();if(!drag.moved){pendingConnection=pendingConnection===drag.id?null:drag.id;selectedConnection=null;updateConnectionBar();notice(pendingConnection?'点击后续卡片上方圆点，或直接拖线到卡片。':'已取消连线。');suppressPortClick=true;setTimeout(()=>suppressPortClick=false,150);return;}suppressPortClick=true;setTimeout(()=>suppressPortClick=false,150);const target=findSnapTarget(event.clientX,event.clientY,drag.id);showSnapTarget(null);if(target)connectNodes(drag.id,target.id);else{pendingConnection=null;updateConnectionBar();notice('未连接：拖到后续卡片或卡片附近即可吸附。');}});
