function installExploration(){
 var root=document.querySelector('.book-reader')||document.querySelector('#workskin'),queued=false;if(!root)return;
 function key(group,route){return '__explore:'+group.getAttribute('data-explore-group')+':'+route.getAttribute('data-explore-route');}
 function terminal(owner){return Array.from(owner.children).some(function(child){if(!child.classList.contains('step-text'))return false;var marker=child.querySelector('.explore-return-page');return marker&&marker.closest('.step-text')===child;});}
 function finish(route){var group=route&&route.parentElement,api=window.paperStoryFlags;if(!route||!group||!api)return;api.completeExploration(key(group,route));route.querySelectorAll('details').forEach(function(el){el.open=false;});route.open=false;group.scrollTop=0;root.dispatchEvent(new Event('paper-exploration-complete'));schedule();}
 function reached(owner){if(owner.closest('[hidden]'))return false;for(var el=owner;el&&el!==root;el=el.parentElement)if(el.tagName==='DETAILS'&&!el.open)return false;return true;}
 function refresh(){queued=false;var api=window.paperStoryFlags;if(!api)return;
 // Old saves may have stopped on the former completion page. Finish that route without showing it.
 root.querySelectorAll('details.explore-route[open],details.explore-route details[open]').forEach(function(owner){if(terminal(owner)&&reached(owner))finish(owner.closest('details.explore-route'));});
 var flags=api.snapshot();root.querySelectorAll('.explore-group').forEach(function(group){var routes=Array.from(group.children).filter(function(el){return el.matches('details.explore-route');}),count=0;routes.forEach(function(route){var done=flags[key(group,route)]===true,badge=route.querySelector('.explore-done');if(done)count++;if(badge)badge.hidden=!done;});var status=group.querySelector('.explore-progress');if(status)status.textContent='已完成 '+count+' / '+routes.length;var next=Array.from(group.children).find(function(el){return el.classList.contains('explore-next');});if(next){var complete=routes.length>0&&count===routes.length;next.hidden=!complete;if(!complete)next.querySelector('details').open=false;}});}
 function schedule(){if(queued)return;queued=true;requestAnimationFrame(refresh);}
 root.addEventListener('click',function(event){var summary=event.target.closest('summary');if(!summary||event.target.closest('a,input,textarea,select,audio,video,button'))return;var owner=summary.parentElement,route=owner.closest('details.explore-route');if(!route||!owner.matches('details.story-step')||!terminal(owner))return;event.preventDefault();event.stopImmediatePropagation();finish(route);});
 root.addEventListener('toggle',schedule,true);window.addEventListener('resize',schedule);window.addEventListener('paper-story-flags-changed',schedule);schedule();
}

