/* Keep original-editor reading positions separate from the graph's viewport. */
const originalViewPositions=new Map();let originalViewContext=null,originalViewRestoreSerial=0;
function originalViewKey(){return book?book.id+':'+book.active:'initial';}
function rememberOriginalViewPosition(){
 if(!originalView||!originalViewContext||originalViewContext!==originalViewKey()||$('editingPaper').hidden)return;
 const top=document.querySelector('.studio-navigation').getBoundingClientRect().height+document.querySelector('.document-bar').getBoundingClientRect().height;
 const children=[...editor.children],anchor=children.find(el=>el.getBoundingClientRect().bottom>top+1);
 originalViewPositions.set(originalViewContext,{x:window.scrollX,y:window.scrollY,node:anchor?.dataset.nodeId||'',index:anchor?children.indexOf(anchor):-1,offset:anchor?anchor.getBoundingClientRect().top-top:0});
}
function prepareOriginalViewSwitch(kind){
 const nextOriginal=kind==='original';if(nextOriginal===originalView)return false;
 rememberOriginalViewPosition();originalViewRestoreSerial++;
 const focus=document.activeElement,stage=$('graphStage');if(focus&&(editor.contains(focus)||stage.contains(focus)))focus.blur();
 const selection=getSelection();if(selection.rangeCount&&(editor.contains(selection.anchorNode)||stage.contains(selection.anchorNode)))selection.removeAllRanges();
 return nextOriginal;
}
function restoreOriginalViewPosition(){
 originalViewContext=originalViewKey();const key=originalViewContext,position=originalViewPositions.get(key),serial=++originalViewRestoreSerial;
 function restore(anchor){if(!originalView||serial!==originalViewRestoreSerial||key!==originalViewKey())return;measureStudioNavigation();const nav=document.querySelector('.studio-navigation').getBoundingClientRect().height,bar=document.querySelector('.document-bar').getBoundingClientRect().height;
 if(position){window.scrollTo(position.x,position.y);if(anchor){const node=(position.node?[...editor.children].find(el=>el.dataset.nodeId===position.node):null)||editor.children[position.index];if(node)window.scrollTo(position.x,Math.max(0,window.scrollY+node.getBoundingClientRect().top-nav-bar-position.offset));}}
 else window.scrollTo(0,Math.max(0,window.scrollY+$('editingPaper').getBoundingClientRect().top-nav-bar));}
 restore(false);requestAnimationFrame(()=>{restore(true);requestAnimationFrame(()=>restore(true));});
}
for(const event of ['wheel','touchstart'])document.addEventListener(event,()=>{originalViewRestoreSerial++;},{passive:true});

function password(text=''){return editBlock('password','密码关卡',editField('','password-answer','正确答案')+editField('no','password-case','区分英文大小写')+editField('答案不对，再试一次。','password-error','失败提示')+editBody(paragraphs(text)));}
function renderPassword(source){const answer=fieldText(source,'password-answer'),sensitive=fieldText(source,'password-case')==='yes',error=fieldText(source,'password-error')||'答案不对，再试一次。',key='__password:'+source.dataset.nodeId;
 if(imageTarget==='ao3')return '<div class="password-gate password-ao3">'+partsHTML(renderParts(source.querySelector('[data-field=body]')))+'<p class="password-help">请先尝试解答，再展开核对答案。</p><details class="password-answer"><summary>查看答案</summary><p>'+esc(answer)+'</p></details><details class="story-step password-next"><summary><span class="option-btn">已核对答案，继续 →</span></summary><!--password-next--></details></div>';
 return '<div class="password-gate" data-password-key="'+esc(key)+'" data-password-answer="'+esc(answer)+'" data-password-case="'+(sensitive?'yes':'no')+'" data-password-error="'+esc(error)+'">'+partsHTML(renderParts(source.querySelector('[data-field=body]')))+'<div class="password-form" role="group" aria-label="密码答案"><label>请输入答案<input type="text" class="password-input" aria-label="输入答案" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="200"></label><button type="button">确认</button></div><p class="password-status" role="status" aria-live="polite"></p><details class="story-step password-next" hidden><summary><span class="option-btn">继续阅读 →</span></summary><!--password-next--></details></div>';}
