 function attempt(form){var gate=form.parentElement,input=form.querySelector('.password-input'),expected=(gate.getAttribute('data-password-answer')||'').trim(),value=input.value.trim(),sensitive=gate.getAttribute('data-password-case')==='yes',status=direct(gate,'.password-status');if(!sensitive){expected=expected.toLowerCase();value=value.toLowerCase();}if(!expected||value!==expected){status.textContent=expected?gate.getAttribute('data-password-error'):'此关卡尚未设置答案。';input.setAttribute('aria-invalid','true');return;}input.removeAttribute('aria-invalid');input.blur();window.paperStoryFlags.solvePassword(gate.getAttribute('data-password-key'));refresh();direct(gate,'.password-next').open=true;root.dispatchEvent(new Event('paper-password-solved'));}
