 if(!visualView||!css)return;const item=visualCurrent();if(!item)return;const source=item.source,type=source.dataset.widget||item.kind,selector=$('visualNode');selector.replaceChildren();for(const [id,node] of graphNodes)selector.add(new Option((node.label||'正文')+' · '+(node.text||'空白页').replace(/\s+/g,' ').slice(0,22),id));selector.value=item.id;
 const all=[...graphNodes.keys()],position=all.indexOf(item.id);$('visualPrev').disabled=position<=0;$('visualNext').disabled=position>=all.length-1;
 const layers=$('visualLayer');const choices=type==='letter'?[['default','信封'],['front','第一张信纸'],['back','第二张信纸']]:type==='journal'?[['default','打开日记']]:type==='polaroid'?[['default','正面'],['back','背面']]:type==='flash'?[['default','底图与正文'],['flash','上层突闪']]:source.querySelector('details.double-text')?[['default','表层文字'],['back','下层文字']]:[['default','正文画面']];layers.replaceChildren(...choices.map(([value,text])=>new Option(text,value)));if(!choices.some(x=>x[0]===visualLayer))visualLayer='default';layers.value=visualLayer;
