function validateTimedBranches(){for(const source of editor.querySelectorAll('[data-widget=branch][data-story-timed=yes]')){if(source.dataset.storyExplore==='yes')continue;const options=Array.from(source.querySelector('[data-field=options]')?.children||[]).filter(el=>el.matches('.branch-option'));if(options.length<2||!options.some(el=>el.dataset.nodeId===source.dataset.storyTimeout))throw Error('限时选择需要至少 1 个普通选项和 1 条超时路线，请在背景 → 限时选择中设置。');}}
