 var items=forks.map(function(fork){var chapter=fork.closest('.reader-chapter'),key=(chapter?chapter.getAttribute('data-chapter-id'):'chapter')+'::'+fork.getAttribute('data-timed-key');return {fork:fork,key:key,total:Math.max(1,Math.min(3600,Number(fork.getAttribute('data-timed-seconds'))||10))*1000,choices:Array.from(fork.children).filter(function(el){return el.matches('details.story-step');}),timeout:fork.getAttribute('data-timed-timeout')};});
 function state(item){return states[item.key]||(states[item.key]={remaining:item.total,deadline:0,done:false});}
 function left(s){return Math.max(0,s.deadline?s.deadline-Date.now():s.remaining);}
 function notify(){if(root.classList.contains('book-reader'))root.dispatchEvent(new Event('paper-sound-state-change'));}
 function visible(item){var el=item.fork;if(document.hidden||el.closest('[hidden]')||root.querySelector('.reader-resume:not([hidden])'))return false;for(var p=el;p&&p!==root;p=p.parentElement){if(getComputedStyle(p).display==='none'||getComputedStyle(p).visibility==='hidden')return false;if(p.tagName==='DETAILS'&&!p.open){var summary=Array.from(p.children).find(function(c){return c.tagName==='SUMMARY';});if(!summary||!summary.contains(el))return false;}}return true;}
 function paint(item,s){var text=item.fork.querySelector('.timed-countdown-text'),meter=item.fork.querySelector('.timed-meter>span'),value=left(s);var seconds=Math.ceil(value/1000);if(text)text.textContent='剩余 '+seconds+' 秒';if(s.second!==seconds){s.second=seconds;notify();}if(meter)meter.style.width=Math.max(0,Math.min(100,value/item.total*100))+'%';}
