/* Layout is stored on the story node, independently of selected text styles. */
var pageLayoutTarget=null;
function pageLayoutSource(){if(graphView)return graphNodes.get(graphSelection)?.source||null;const selection=getSelection(),node=selection.anchorNode,el=node?.nodeType===1?node:node?.parentElement;if(el&&editor.contains(el)){graphProjection(editor);return el.closest('[data-widget],[data-node-id]');}return pageLayoutTarget?.isConnected&&editor.contains(pageLayoutTarget)?pageLayoutTarget:null;}
function syncPageLayoutControls(source){pageLayoutTarget=source||null;if(!$('pageTextAlign'))return;$('pageTextAlign').value=source?.dataset.textAlign||'';$('pageTextPosition').value=source?.dataset.pagePosition||'';}
function applyPageLayoutClasses(page,source){if(!page||!source)return;for(const cls of [...page.classList])if(/^page-(?:text|pos)-/.test(cls))page.classList.remove(cls);const align=source.dataset.textAlign,position=source.dataset.pagePosition;if(['left','center','right'].includes(align))page.classList.add('page-text-'+align);if(['top','center','bottom'].includes(position))page.classList.add('page-pos-'+position);}
function decoratePageLayouts(parts,root){const sources=Array.from(root.querySelectorAll('[data-node-id]'));for(const part of parts){const source=sources.find(el=>el.dataset.nodeId===part.nodeId);if(!source||!source.dataset.textAlign&&!source.dataset.pagePosition)continue;const align=['left','center','right'].includes(source.dataset.textAlign)?' page-text-'+source.dataset.textAlign:'',position=['top','center','bottom'].includes(source.dataset.pagePosition)?' page-pos-'+source.dataset.pagePosition:'';const open='<div class="paper-page-layout'+align+position+'">';if(part.branch)part.branch.prompt=open+part.branch.prompt+'</div>';else part.html=open+part.html+'</div>';}}
function resolvePageLayouts(root){for(const marker of root.querySelectorAll('.paper-page-layout')){const page=marker.closest('.step-text');if(page){for(const cls of marker.classList)if(/^page-(?:text|pos)-/.test(cls))page.classList.add(cls);marker.replaceWith(...marker.childNodes);}else marker.classList.remove('paper-page-layout');}}
function revealToolSection(control){for(let section=control?.closest('details.tool-section');section;section=section.parentElement?.closest('details.tool-section'))section.open=true;}
$('applyPageLayout').onmousedown=$('resetPageLayout').onmousedown=event=>event.preventDefault();
function commitPageLayout(reset=false){const source=pageLayoutSource();if(!source?.isConnected)return notice('请先选中一个剧情节点或点击原文中的段落。');if(source.matches('.branch-option'))return notice('选项标题是按钮，请选择该路线下方的剧情节点再设置排版。');checkpoint();for(const [key,value] of [['textAlign',$('pageTextAlign').value],['pagePosition',$('pageTextPosition').value]]){if(!reset&&value)source.dataset[key]=value;else delete source.dataset[key];}checkpoint();if(graphView)renderGraph(source);else syncPageLayoutControls(source);notice(reset?'已恢复此页的默认排版。':'本页排版已保存；在画面编辑或看示例中查看。');}
