function timedBranch(text=''){const host=document.createElement('div');host.innerHTML=branch(text);const source=host.firstElementChild;source.dataset.storyTimed='yes';source.dataset.storySeconds='10';source.dataset.storyAuto='no';const options=source.querySelector('[data-field=options]');options.insertAdjacentHTML('beforeend',optionEditor('超时未操作',''));graphProjection(host);source.dataset.storyTimeout=options.lastElementChild.dataset.nodeId;const caption=source.querySelector('.block-caption>span');if(caption)caption.textContent='限时分支';return host.innerHTML;}
