function isChoiceLabelSelection(parent,surface){if(surface?.closest('.graph-card.choice')||parent.closest('[data-field=option-title]'))return true;const visual=parent.closest('[data-visual-key]');return !!(visual&&visualBindings.get(visual.dataset.visualKey)?.field?.dataset.field==='option-title');}
function sanitizeChoiceLabel(markup){const host=document.createElement('div');host.innerHTML=sanitizeDocument(markup);const allowed=new Set(['SPAN','B','STRONG','I','EM','U','S','BR','DETAILS','SUMMARY']);for(const el of Array.from(host.querySelectorAll('*')).reverse()){if(el.getAttribute('aria-hidden')==='true'){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}if(el.tagName==='DETAILS'&&!el.classList.contains('inline-spoiler')){el.replaceWith(...el.childNodes);continue;}for(const attr of Array.from(el.attributes))if(attr.name!=='class')el.removeAttribute(attr.name);if(el.tagName==='DETAILS')el.className='inline-spoiler';else if(el.tagName==='SPAN'){el.className=Array.from(el.classList).filter(c=>['inline-red-text','text-style','text-bold','text-large','text-huge'].includes(c)).join(' ');}else el.removeAttribute('class');if(!el.className)el.removeAttribute('class');}return host.innerHTML;}
function choiceLabelParts(field){if(!field)return {};const host=document.createElement('div');host.innerHTML=sanitizeChoiceLabel(field.innerHTML);if(!host.textContent.trim())return {};
 function render(node,masked){if(node.nodeType===3)return esc(node.textContent);if(node.nodeType!==1)return '';if(node.tagName==='BR')return '<br>';if(node.matches('details.inline-spoiler')){const summary=node.querySelector(':scope > summary');const text=esc(summary?.textContent||'');return '<span class="'+(masked?'choice-label-cover':'inline-red-text')+'">'+text+'</span>';}const tag=['B','STRONG','I','EM','U','S'].includes(node.tagName)?node.tagName.toLowerCase():'span',className=node.tagName==='SPAN'?node.className:'';return '<'+tag+(className?' class="'+esc(className)+'"':'')+'>'+Array.from(node.childNodes).map(child=>render(child,masked)).join('')+'</'+tag+'>';}
 return {labelHTML:Array.from(host.childNodes).map(node=>render(node,false)).join(''),maskedLabelHTML:Array.from(host.childNodes).map(node=>render(node,true)).join(''),labelMasked:!!host.querySelector('details.inline-spoiler')};
}
function choiceLabelHTML(option){return option.labelHTML||esc(option.label||'选项');}
function choiceMaskControl(option){if(!option.labelMasked)return '';return '<details class="choice-label-mask"><summary class="option-btn" aria-label="展开此选项的遮盖文字">'+(option.maskedLabelHTML||esc(option.label))+'</summary></details>';}

function emitSurfaceInput(surface){if(visualSurfaceBindings.has(surface))return writeVisualSurface(surface);surface.dispatchEvent(new Event('input',{bubbles:true}));return true;}
function writeVisualSurface(surface){const binding=visualSurfaceBindings.get(surface);if(!visualView||!binding?.field?.isConnected||!binding.source.isConnected||binding.nodeId!==graphSelection)return false;checkpoint();if(binding.plain)binding.field.textContent=surface.textContent;else if(binding.field.dataset.field==='option-title')binding.field.innerHTML=sanitizeChoiceLabel(surface.innerHTML);else{const copy=surface.cloneNode(true);copy.querySelectorAll('.visual-art-editing').forEach(el=>el.classList.remove('visual-art-editing'));binding.field.innerHTML=sanitizeDocument(copy.innerHTML);refreshFontLayers(binding.field);}const item=graphNodes.get(binding.nodeId);if(item)item.text=editorText(binding.source);for(const input of $('effectInspectorBody').querySelectorAll('[data-graph-field]'))if(input.dataset.graphField===binding.field.dataset.field&&'value' in input)input.value=binding.field.textContent;const labels={'sms-name':'联系人名称','sms-draft':'未发送的文字'};if(labels[binding.field.dataset.field]){const input=$('effectInspectorBody').querySelector('input[aria-label="'+labels[binding.field.dataset.field]+'"]');if(input)input.value=binding.field.textContent;}visualDirty=true;$('undo').disabled=false;$('redo').disabled=true;clearTimeout(timer);timer=setTimeout(checkpoint,350);persist();return true;}

function normalizeBlurParagraphs(){for(const paragraph of editor.querySelectorAll('p')){if(!paragraph.querySelector('.details-inline-blur'))continue;const block=document.createElement('div');for(const attr of paragraph.attributes)block.setAttribute(attr.name,attr.value);block.append(...paragraph.childNodes);paragraph.replaceWith(block);for(const item of graphNodes.values()){if(item.source===paragraph)item.source=block;if(item.textSource===paragraph)item.textSource=block;}if(visualView)for(const surface of $('visualFrame').contentDocument?.querySelectorAll('[data-visual-key]')||[]){const binding=visualSurfaceBindings.get(surface);if(binding?.source===paragraph)binding.source=block;if(binding?.field===paragraph)binding.field=block;}}}
function blurLevelOf(el){return ['1','2','3'].find(level=>el.classList.contains('blur-'+level))||'1';}
$('applyBlur').addEventListener('mousedown',event=>event.preventDefault());
$('applyBlur').onclick=()=>{
 if(!fontRange||fontRange.collapsed||!fontRange.commonAncestorContainer.isConnected)return notice('请先在正文或纸面内选中文字。');
 const range=fontRange.cloneRange(),parent=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement,surface=parent.closest('.paper-surface'),host=surface||parent.closest('[data-editable]')||editor;
 if(!host.contains(range.startContainer)||!host.contains(range.endContainer)||isChoiceLabelSelection(parent,surface))return notice('请在同一块剧情正文或纸面内应用字体模糊。');
 if(range.cloneContents().querySelector('[data-widget]'))return notice('请在同一块正文内选择文字。');
 checkpoint();const level=['1','2','3'].includes($('blurLevel').value)?$('blurLevel').value:'1',existing=parent.closest('.details-inline-blur');
 if(existing&&host.contains(existing)){existing.className='details-inline-blur blur-'+level;}
 else{const details=parent.ownerDocument.createElement('details'),summary=parent.ownerDocument.createElement('summary');details.className='details-inline-blur blur-'+level;const content=range.extractContents();content.querySelectorAll('.details-inline-blur').forEach(el=>el.replaceWith(...el.querySelector('summary').childNodes));summary.append(content);details.append(summary);details.open=true;range.insertNode(details);}
 if(surface)emitSurfaceInput(surface);else setEditable();normalizeBlurParagraphs();checkpoint();persist();fontRange=null;savedRange=null;getSelection().removeAllRanges();paintAppliedEffects(host);notice('字体模糊已应用；请在看示例中点击文字查看清晰效果。');
};

const readerContentFitCSS='.node-story{width:100%;height:100%}.node-frame[hidden]{display:none!important}.node-frame{width:100%;height:100%}.node-jump{display:none!important}#workskin .reader-fit-page>.step-inner>.effect-page-content{z-index:2;pointer-events:none}#workskin .reader-fit-page>.step-inner>.effect-page-content details,#workskin .reader-fit-page>.step-inner>.effect-page-content summary,#workskin .reader-fit-page>.step-inner>.effect-page-content button,#workskin .reader-fit-page>.step-inner>.effect-page-content input,#workskin .reader-fit-page>.step-inner>.effect-page-content a,#workskin .reader-fit-page>.step-inner>.effect-page-content audio,#workskin .reader-fit-page>.step-inner>.effect-page-content video,#workskin .reader-fit-page>.step-inner>.effect-page-content .imessage,#workskin .reader-fit-page>.step-inner>.effect-page-content .journal-scene,#workskin .reader-fit-page>.step-inner>.effect-page-content .trifold_letter,#workskin .reader-fit-page>.step-inner>.effect-page-content .record-player{pointer-events:auto}#workskin .step-text.reader-fit-page,#workskin .fork-container.reader-fit-page{overflow:hidden}#workskin .reader-fit-page>.step-inner{position:relative;height:100%;min-height:100%}#workskin .text-appear-scroll.text-scroll-active{display:block;overflow:hidden;position:relative}#workskin .text-scroll-track{display:block;will-change:transform}';
function installReaderContentFit(){
 var queued=false,busy=false,until=0;
 function fit(){queued=false;if(busy)return;busy=true;document.querySelectorAll('#workskin .step-text,#workskin .fork-container').forEach(function(page){if(page.closest('[hidden]')||!page.getClientRects().length)return;var rect=page.getBoundingClientRect(),hit=document.elementFromPoint(Math.max(0,Math.min(innerWidth-1,rect.left+rect.width/2)),Math.max(0,Math.min(innerHeight-1,rect.top+rect.height/2)));if(hit&&hit.closest('.step-text,.fork-container')!==page)return;var inner=Array.from(page.children).find(function(el){return el.classList.contains('step-inner');});if(!inner)return;var content=Array.from(inner.children).find(function(el){return el.matches('.text-content,.effect-page-content,.fork-content');});if(!content||content.matches('.fork-content')||content.querySelector('.game-container,.step-text'))return;var height=page.clientHeight,width=page.clientWidth;if(!height||!width)return;
 page.classList.add('reader-fit-page');content.style.position='absolute';content.style.left='50%';content.style.top='0';content.style.width='100%';content.style.margin='0';content.style.transform='none';content.style.transformOrigin='top center';
 var natural=content.offsetHeight;if(!content.querySelector('.font-scatter'))natural=Math.max(natural,content.scrollHeight);if(content.matches('.text-content')&&!content.querySelector('.font-scatter,.text-scroll-active')&&natural>height*2){page.classList.remove('reader-fit-page');content.style.position='';content.style.left='';content.style.top='';content.style.width='';content.style.margin='';content.style.transform='';content.style.transformOrigin='';return;}var scale=Math.min(1,(height-8)/Math.max(1,natural)),position=page.classList.contains('page-pos-top')?'top':page.classList.contains('page-pos-bottom')?'bottom':'center',used=natural*scale,top=position==='top'?0:position==='bottom'?Math.max(0,height-used):Math.max(0,(height-used)/2);
 content.style.top=top+'px';content.style.transform='translateX(-50%) scale('+scale+')';page.scrollTop=0;
 });busy=false;if(performance.now()<until)requestAnimationFrame(schedule);}
 function schedule(){if(!queued){queued=true;requestAnimationFrame(fit);}}
 function settle(){until=performance.now()+2300;schedule();}
 window.addEventListener('resize',schedule);document.addEventListener('toggle',settle,true);document.addEventListener('click',settle,true);document.addEventListener('change',schedule,true);document.addEventListener('paper-content-layout',schedule);document.addEventListener('transitionend',schedule,true);document.addEventListener('load',schedule,true);if(window.ResizeObserver){var observer=new ResizeObserver(schedule);document.querySelectorAll('#workskin .game-container').forEach(function(game){observer.observe(game);});}if(document.fonts&&document.fonts.ready)document.fonts.ready.then(schedule);schedule();
}

function graphSuccessors(node){if(node.kind==='branch')return node.choices.map(c=>c.id).concat(node.branch.explore?[node.next]:[]);if(node.kind==='choice')return [node.override===undefined?node.next:node.override];if(node.kind==='page')return node.part.storyEnd?[]:[node.override===undefined?node.next:node.override];return [];}
function analyzeStoryGraph(nodes,start){const colors=new Map(),order=[],stack=start&&start!=='__end__'?[[start,false]]:[];while(stack.length){const [id,done]=stack.pop();if(!id||id==='__end__')continue;const node=nodes.get(id);if(!node)throw Error('有一条连线的目标已不存在，请在工作台重新连接。');if(done){colors.set(id,2);order.push(id);continue;}if(colors.get(id)===2)continue;if(colors.get(id)===1)throw Error('连线形成循环，请断开回跳连线；需要反复探索时请使用探索分支。');colors.set(id,1);stack.push([id,true]);for(const next of graphSuccessors(node).reverse())if(next&&next!=='__end__')stack.push([next,false]);}return order;}
function estimateStoryGraph(nodes,start){const sizes=new Map(),order=analyzeStoryGraph(nodes,start),size=id=>id&&id!=='__end__'?sizes.get(id)||0:0;for(const id of order){const node=nodes.get(id);let length=0;if(node.kind==='choice')length=size(node.override===undefined?node.next:node.override);else if(node.kind==='branch')length=(node.prompt||'').length+1200+node.choices.reduce((sum,c)=>sum+(c.labelHTML||c.label||'').length+400+size(c.id),0)+(node.branch.explore?size(node.next):0);else if(node.kind==='page')length=(node.part.html||'').length+500+(node.part.storyEnd?0:size(node.override===undefined?node.next:node.override));else length=100;sizes.set(id,Math.min(Number.MAX_SAFE_INTEGER,length));}return size(start);}
function renderNodeStory(parts,startId=''){
 const {nodes,start}=indexStoryGraph(parts),entry=startId&&nodes.has(startId)?startId:start,order=analyzeStoryGraph(nodes,entry),endKey='__paper_reader_end__';const included=new Set(order);for(let i=0;i<order.length;i++){const n=nodes.get(order[i]);if(n.kind==='exploreReturn'&&!included.has(n.group))for(const id of analyzeStoryGraph(nodes,n.group))if(!included.has(id)){included.add(id);order.push(id);}}const sourceOrder=new Map(Array.from(editor.querySelectorAll('[data-node-id]')).map((el,i)=>[el.dataset.nodeId,i]));order.sort((a,b)=>(sourceOrder.get(a)??Number.MAX_SAFE_INTEGER)-(sourceOrder.get(b)??Number.MAX_SAFE_INTEGER));
 function target(id){const seen=new Set();while(id&&id!=='__end__'&&nodes.get(id)?.kind==='choice'){if(seen.has(id))throw Error('选项连线形成循环。');seen.add(id);const node=nodes.get(id);id=node.override===undefined?node.next:node.override;}return id&&id!=='__end__'?id:endKey;}
 const jump=id=>'<span class="node-jump" data-node-target="'+esc(target(id))+'" hidden></span>',frames=[];
 for(const id of order){const node=nodes.get(id);if(node.kind==='choice')continue;let html='';if(node.kind==='exploreReturn')html='<span class="node-explore-return" data-node-group="'+esc(node.group)+'" data-node-route="'+esc(node.route)+'" hidden></span>';
 else if(node.kind==='branch')html=node.branch.explore?renderExploreBranch(node.branch,jump(node.next),node.choices.map(c=>jump(c.id))):renderChoiceBranch({...node.branch,options:node.choices},c=>jump(c.id));
 else{const next=node.override===undefined?node.next:node.override,continuation=jump(next);html=node.part.storyEnd?renderEndingPage(node.part):node.part.gate?renderPasswordPage(node.part,continuation):node.part.effect?effectPage(node.part.html,continuation):'<details class="story-step"><summary>'+page(node.part.html)+'<span class="step-hint">点击本页空白处，继续阅读 →</span></summary>'+continuation+'</details>';}
 frames.push('<div class="node-frame" data-node-key="'+esc(id)+'"'+(id===target(entry)?'':' hidden')+'>'+html+'</div>');}
 frames.push('<div class="node-frame" data-node-key="'+endKey+'"'+(target(entry)===endKey?'':' hidden')+'>'+page('<p>本章已结束</p>')+'</div>');return '<div class="node-story" data-node-root="yes" data-node-start="'+esc(target(entry))+'">'+frames.join('')+'</div>';
}
function installNodeStory(){
 var roots=Array.from(document.querySelectorAll('[data-node-root]')),states=new Map();if(!roots.length)return;
 function announce(root){root.dispatchEvent(new Event('paper-node-change',{bubbles:true}));document.dispatchEvent(new Event('paper-content-layout'));window.dispatchEvent(new Event('resize'));}
 function go(root,id,reset){var state=states.get(root),frame=state&&state.frames.get(id);if(!frame)return false;var back=frame.querySelector('.node-explore-return');if(back){var flags=window.paperStoryFlags;if(flags)flags.completeExploration('__explore:'+back.getAttribute('data-node-group')+':'+back.getAttribute('data-node-route'));root.dispatchEvent(new Event('paper-exploration-complete',{bubbles:true}));return go(root,back.getAttribute('data-node-group'),true);}if(reset)frame.querySelectorAll('details').forEach(function(d){d.open=false;});state.current=id;state.frames.forEach(function(el){el.hidden=el!==frame;});frame.querySelectorAll('.step-text,.fork-container').forEach(function(el){el.scrollTop=0;});announce(root);return true;}
 roots.forEach(function(root){var frames=new Map();Array.from(root.children).forEach(function(frame){frames.set(frame.getAttribute('data-node-key'),frame);});states.set(root,{frames:frames,current:root.getAttribute('data-node-start')});root.addEventListener('toggle',function(event){var detail=event.target;if(!detail.open||!detail.matches('details.story-step')||detail.closest('[hidden]'))return;var marker=Array.from(detail.children).find(function(child){return child.classList.contains('node-jump');});if(marker)go(root,marker.getAttribute('data-node-target'),true);},true);});
 function rootsIn(scope){return roots.filter(function(root){return root===scope||scope.contains(root);});}
 window.paperNodeReader={snapshot:function(scope){return rootsIn(scope).map(function(root){return {start:root.getAttribute('data-node-start'),current:states.get(root).current};});},restore:function(scope,records){rootsIn(scope).forEach(function(root){var record=Array.isArray(records)&&records.find(function(r){return r&&r.start===root.getAttribute('data-node-start');});go(root,record&&record.current||root.getAttribute('data-node-start'),false);});},reset:function(scope){rootsIn(scope).forEach(function(root){root.querySelectorAll('details').forEach(function(d){d.open=false;});go(root,root.getAttribute('data-node-start'),true);});}};
 var work=document.querySelector('#workskin');if(work&&!document.querySelector('.book-reader'))work.addEventListener('click',function(event){if(event.target.closest('.story-ending,.story-ending-page')&&!event.target.closest('summary,a,button,input,textarea,select,audio,video,details.double-text,details.inline-spoiler,details.details-inline-blur,details.stack-spoiler'))window.paperNodeReader.reset(work);});
}

$('exportAO3Chapters').onclick=async()=>{
 const button=$('exportAO3Chapters'),report=$('ao3Report');checkpoint();syncChapter();const original=editor.innerHTML,settings=chapterSettings(),files=[],lines=['AO3 分章导出检查','每个 HTML 对应纸间中已保存的一章；请在 AO3 新建对应章节并粘贴。','50 万 HTML 字符为纸间导出预检阈值，45 万以上建议拆分。',''];button.disabled=true;$('outputPanel').hidden=false;report.hidden=false;report.textContent='正在逐章检查…';let failed=0;
 try{for(let i=0;i<book.chapters.length;i++){const chapter=book.chapters[i],name=(chapter.title||'第'+(i+1)+'章').replace(/[\\/:*?"<>|]/g,'-');editor.innerHTML=chapter.html;applySettings(chapter.settings);try{const html=renderHTML('ao3');if(html.length>500000)throw Error('实际 HTML 超过 50 万字符，请拆分本章');files.push({name:String(i+1).padStart(2,'0')+'-'+name+'.html',data:html});lines.push('可导出 · '+name+'：'+html.length.toLocaleString()+' HTML 字符'+(html.length>450000?'（偏大，建议拆分）':''));}catch(error){failed++;lines.push('未导出 · '+name+'：'+error.message);}report.textContent=lines.join('\n');await new Promise(resolve=>setTimeout(resolve,0));}
 files.push({name:'通用CSS.css',data:css},{name:'导出检查.txt',data:lines.join('\n')});const zip=await makeMinitoolZIP(files);download('纸间-AO3分章包.zip',zip,'application/zip');report.textContent=lines.join('\n')+'\n\n已生成分章包；'+failed+' 章需修改后重新导出。';notice('AO3 分章包已下载；请查看逐章检查结果。');
 }catch(error){report.textContent=lines.join('\n')+'\n导出失败：'+error.message;notice(error.message);}finally{editor.innerHTML=original;applySettings(settings);setEditable();savedRange=null;if(graphView)renderGraph();button.disabled=false;}
};
